            if(out.isEmpty() || cur[0]>out.get(out.size()-1)[1]) out.add(cur.clone());
            else out.get(out.size()-1)[1]=Math.max(out.get(out.size()-1)[1],cur[1]);
        }
        return out.toArray(new int[out.size()][]);
    }
}

