class Solution:
    def topKFrequent(self, nums, k):
        freq = {}
        for x in nums:
            freq[x] = freq.get(x, 0) + 1
        buckets = [[] for _ in range(len(nums) + 1)]
        for x, count in freq.items():
            buckets[count].append(x)
        result = []
        for bucket in reversed(buckets):
            result.extend(bucket)
            if len(result) >= k:
                return result[:k]
        return result

