import java.util.*;
class Solution {
    public int[] topKFrequent(int[] nums,int k){
        Map<Integer,Integer> f=new HashMap<>();for(int x:nums)f.put(x,f.getOrDefault(x,0)+1);
        PriorityQueue<int[]> pq=new PriorityQueue<>(Comparator.comparingInt(a->a[1]));
        for(var e:f.entrySet()){pq.offer(new int[]{e.getKey(),e.getValue()});if(pq.size()>k)pq.poll();}
        int[] ans=new int[k];for(int i=k-1;i>=0;i--)ans[i]=pq.poll()[0];return ans;
    }
}

