    public boolean isValidSudoku(char[][] board){
        boolean[][] r=new boolean[9][9],c=new boolean[9][9],b=new boolean[9][9];
        for(int i=0;i<9;i++)for(int j=0;j<9;j++)if(board[i][j]!='.'){
            int x=board[i][j]-'1', box=(i/3)*3+j/3;
            if(r[i][x]||c[j][x]||b[box][x])return false;
            r[i][x]=c[j][x]=b[box][x]=true;
        }
        return true;
    }
}

