import java.util.*;
class Solution {
    public String minWindow(String s,String t){
        Map<Character,Integer> need=new HashMap<>(),have=new HashMap<>();for(char c:t.toCharArray())need.put(c,need.getOrDefault(c,0)+1);
        int formed=0,req=need.size(),l=0,bestLen=Integer.MAX_VALUE,bs=0;
        for(int r=0;r<s.length();r++){char c=s.charAt(r);have.put(c,have.getOrDefault(c,0)+1);if(need.containsKey(c)&&have.get(c).intValue()==need.get(c))formed++;
            while(formed==req){if(r-l+1<bestLen){bestLen=r-l+1;bs=l;}char x=s.charAt(l++);have.put(x,have.get(x)-1);if(need.containsKey(x)&&have.get(x)<need.get(x))formed--;}
        }return bestLen==Integer.MAX_VALUE?"":s.substring(bs,bs+bestLen);
    }
}

