class Solution:
    def findAnagrams(self, s, p):
        if len(p) > len(s):
            return []
        need = [0] * 26
        window = [0] * 26
        for ch in p:
            need[ord(ch) - 97] += 1
        result = []
        m = len(p)
        for i, ch in enumerate(s):
            window[ord(ch) - 97] += 1
            if i >= m:
                window[ord(s[i - m]) - 97] -= 1
            if window == need:
                result.append(i - m + 1)
        return result

