class Solution {
    public String longestPalindrome(String s){
        if(s.length()<2)return s;int bestL=0,bestR=1;
        for(int i=0;i<s.length();i++){int[] a=expand(s,i,i),b=expand(s,i,i+1);if(a[1]-a[0]>bestR-bestL){bestL=a[0];bestR=a[1];}if(b[1]-b[0]>bestR-bestL){bestL=b[0];bestR=b[1];}}
        return s.substring(bestL,bestR);
    }
    private int[] expand(String s,int l,int r){while(l>=0&&r<s.length()&&s.charAt(l)==s.charAt(r)){l--;r++;}return new int[]{l+1,r};}
}

