    string longestPalindrome(string s){if(s.size()<2)return s;int bl=0,br=1;auto ex=[&](int l,int r){while(l>=0&&r<s.size()&&s[l]==s[r])--l,++r;return pair<int,int>{l+1,r};};for(int i=0;i<s.size();i++){auto a=ex(i,i),b=ex(i,i+1);if(a.second-a.first>br-bl)bl=a.first,br=a.second;if(b.second-b.first>br-bl)bl=b.first,br=b.second;}return s.substr(bl,br-bl);}
};

