    def isAnagram(self, s, t):
        if len(s) != len(t):
            return False
        count = {}
        for ch in s:
            count[ch] = count.get(ch, 0) + 1
        for ch in t:
            count[ch] = count.get(ch, 0) - 1
            if count[ch] < 0:
                return False
        return True

