class Solution {
    public boolean isValid(String s){
        Map<Character,Character> p=Map.of(')','(','}', '{',']','[');Deque<Character> st=new ArrayDeque<>();
        for(char c:s.toCharArray()){if(p.containsKey(c)){if(st.isEmpty()||st.pop()!=p.get(c))return false;}else st.push(c);}return st.isEmpty();
    }
}

