class Solution {
    public ListNode addTwoNumbers(ListNode l1,ListNode l2){
        ListNode d=new ListNode(0),t=d;int carry=0;
        while(l1!=null||l2!=null||carry!=0){int sum=carry;if(l1!=null){sum+=l1.val;l1=l1.next;}if(l2!=null){sum+=l2.val;l2=l2.next;}t.next=new ListNode(sum%10);t=t.next;carry=sum/10;}return d.next;
    }
}

