import java.util.*;
class Solution {
    public Node copyRandomList(Node head){
        if(head==null)return null;Map<Node,Node> m=new HashMap<>();for(Node c=head;c!=null;c=c.next)m.put(c,new Node(c.val));
        for(Node c=head;c!=null;c=c.next){m.get(c).next=m.get(c.next);m.get(c).random=m.get(c.random);}return m.get(head);
    }
}

