class MinStack:
    def __init__(self):
        self.stack = []
        self.minimums = []

    def push(self, val):
        self.stack.append(val)
        if not self.minimums:
            self.minimums.append(val)
        else:
            self.minimums.append(min(val, self.minimums[-1]))

    def pop(self):
        self.stack.pop()
        self.minimums.pop()

    def top(self):
        return self.stack[-1]

    def getMin(self):
        return self.minimums[-1]

