    public int[] nextGreaterElement(int[] nums1,int[] nums2){
        Map<Integer,Integer> m=new HashMap<>();Deque<Integer> st=new ArrayDeque<>();
        for(int x:nums2){while(!st.isEmpty()&&st.peek()<x)m.put(st.pop(),x);st.push(x);}
