import java.util.*;
class Solution {
    public int evalRPN(String[] tokens){
        Deque<Integer> st=new ArrayDeque<>();
        for(String x:tokens){if(x.equals("+")||x.equals("-")||x.equals("*")||x.equals("/")){int b=st.pop(),a=st.pop();switch(x){case "+":st.push(a+b);break;case "-":st.push(a-b);break;case "*":st.push(a*b);break;default:st.push(a/b);}}else st.push(Integer.parseInt(x));}return st.pop();
    }
}

