class Solution {
    public int largestRectangleArea(int[] h){
        Deque<Integer> st=new ArrayDeque<>();int best=0;
        for(int i=0;i<=h.length;i++){int cur=i==h.length?0:h[i];while(!st.isEmpty()&&h[st.peek()]>cur){int height=h[st.pop()];int left=st.isEmpty()?-1:st.peek();best=Math.max(best,height*(i-left-1));}st.push(i);}return best;
    }
}

