import java.util.*;
class Solution {
    public int carFleet(int target,int[] position,int[] speed){
        Integer[] idx=new Integer[position.length];for(int i=0;i<idx.length;i++)idx[i]=i;Arrays.sort(idx,(a,b)->Integer.compare(position[b],position[a]));
        int fleets=0;double last=0;for(int i:idx){double time=(double)(target-position[i])/speed[i];if(time>last){fleets++;last=time;}}return fleets;
    }
}

