class Solution:
    def searchRange(self, nums, target):
        def lower_bound(x):
            left, right = 0, len(nums)
            while left < right:
                mid = (left + right) // 2
                if nums[mid] < x:
                    left = mid + 1
                else:
                    right = mid
            return left
        left = lower_bound(target)
        right = lower_bound(target + 1) - 1
        if left == len(nums) or nums[left] != target:
            return [-1, -1]
        return [left, right]

