import java.util.*;
class Solution {
    private int pre;
    private Map<Integer,Integer> pos;
    public TreeNode buildTree(int[] preorder,int[] inorder){pos=new HashMap<>();for(int i=0;i<inorder.length;i++)pos.put(inorder[i],i);pre=0;return build(preorder,0,inorder.length-1);}
    private TreeNode build(int[] p,int l,int r){if(l>r)return null;int v=p[pre++];TreeNode n=new TreeNode(v);int m=pos.get(v);n.left=build(p,l,m-1);n.right=build(p,m+1,r);return n;}
}

