class Solution:
    def canFinish(self, numCourses, prerequisites):
        graph = [[] for _ in range(numCourses)]
        for course, prereq in prerequisites:
            graph[prereq].append(course)
        state = [0] * numCourses
        def dfs(v):
            if state[v] == 1:
                return False
            if state[v] == 2:
                return True
            state[v] = 1
            for nei in graph[v]:
                if not dfs(nei):
                    return False
            state[v] = 2
            return True
        return all(dfs(v) for v in range(numCourses) if state[v] == 0)

