import java.util.*;
class Solution {
    public List<List<Integer>> pacificAtlantic(int[][] h){int m=h.length,n=h[0].length;boolean[][]p=new boolean[m][n],a=new boolean[m][n];for(int i=0;i<m;i++){dfs(h,p,i,0);dfs(h,a,i,n-1);}for(int j=0;j<n;j++){dfs(h,p,0,j);dfs(h,a,m-1,j);}List<List<Integer>>r=new ArrayList<>();for(int i=0;i<m;i++)for(int j=0;j<n;j++)if(p[i][j]&&a[i][j])r.add(Arrays.asList(i,j));return r;}
    private void dfs(int[][]h,boolean[][]v,int r,int c){if(v[r][c])return;v[r][c]=true;int[][]d={{1,0},{-1,0},{0,1},{0,-1}};for(int[]z:d){int x=r+z[0],y=c+z[1];if(x>=0&&x<h.length&&y>=0&&y<h[0].length&&!v[x][y]&&h[x][y]>=h[r][c])dfs(h,v,x,y);}}
}

