class Solution:
    def isBipartite(self, graph):
        from collections import deque
        color = {}
        for start in range(len(graph)):
            if start in color:
                continue
            color[start] = 0
            q = deque([start])
            while q:
                v = q.popleft()
                for nei in graph[v]:
                    if nei not in color:
                        color[nei] = color[v] ^ 1
                        q.append(nei)
                    elif color[nei] == color[v]:
                        return False
        return True

