class Solution {
    public boolean isBipartite(int[][] g){int[] c=new int[g.length];for(int s=0;s<g.length;s++)if(c[s]==0){Queue<Integer>q=new ArrayDeque<>();q.add(s);c[s]=1;while(!q.isEmpty()){int u=q.poll();for(int v:g[u]){if(c[v]==0){c[v]=-c[u];q.add(v);}else if(c[v]==c[u])return false;}}}return true;}
