class Solution:
    def longestCommonSubsequence(self, text1, text2):
        if len(text1) < len(text2):
            text1, text2 = text2, text1
        prev = [0] * (len(text2) + 1)
        for a in text1:
            curr = [0]
            for j, b in enumerate(text2, 1):
                curr.append(prev[j - 1] + 1 if a == b else max(prev[j], curr[-1]))
            prev = curr
        return prev[-1]

