class Solution {
    public List<List<Integer>> permute(int[] nums){List<List<Integer>>r=new ArrayList<>();back(nums,0,r);return r;}
    private void back(int[]a,int s,List<List<Integer>>r){if(s==a.length){List<Integer>x=new ArrayList<>();for(int v:a)x.add(v);r.add(x);return;}for(int i=s;i<a.length;i++){int t=a[s];a[s]=a[i];a[i]=t;back(a,s+1,r);t=a[s];a[s]=a[i];a[i]=t;}}
}

